        String s = br.readLine().trim();
        int n = s.length(), bestStart = 0, bestLen = 1;
        for (int c = 0; c < n; c++) {
            for (int t = 0; t < 2; t++) {
                int lo = c, hi = c + t;
                while (lo >= 0 && hi < n && s.charAt(lo) == s.charAt(hi)) { lo--; hi++; }
                int len = hi - lo - 1, start = lo + 1;
                if (len > bestLen || (len == bestLen && start < bestStart)) { bestStart = start; bestLen = len; }
            }
        }
        System.out.println(s.substring(bestStart, bestStart + bestLen));
    }
}

